import axios from 'axios';

// ── Instance Axios centrale ──────────────────────────────────────────────────
const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8080/api',
  headers: { 'Content-Type': 'application/json' },
  timeout: 10000,
});

// ── Intercepteur réponse : unwrap ApiResponse + message d'erreur lisible ─────
api.interceptors.response.use(
  (response) => response,
  (error) => {
    const message =
      error.response?.data?.message ||
      error.response?.data?.error ||
      'Une erreur est survenue';
    return Promise.reject(new Error(message));
  }
);

// ── Mapping rôles backend → frontend ─────────────────────────────────────────
// Backend  : ADMIN | RECEPTIONNISTE | CLIENT
// Frontend : admin | receptionist   | client
const normalizeRole = (role) => {
  if (!role) return 'client';
  const map = {
    ADMIN: 'admin',
    RECEPTIONNISTE: 'receptionist',
    CLIENT: 'client',
  };
  return map[role.toUpperCase()] ?? role.toLowerCase();
};

// ── Helper : extrait { token, user } depuis ApiResponse<AuthResponse> ────────
const extractAuth = (apiResponse) => {
  // Le backend renvoie : { success, message, data: { token, tokenType, expiresIn, user } }
  const data = apiResponse.data?.data ?? apiResponse.data;
  const token = data?.token ?? data?.accessToken;
  const rawUser = data?.user;

  if (!token || !rawUser) throw new Error('Réponse serveur invalide');

  const user = {
    id:    rawUser.id,
    name:  rawUser.name,
    email: rawUser.email,
    role:  normalizeRole(rawUser.role),
    active: rawUser.active,
  };

  return { token, user };
};

// ── authService ───────────────────────────────────────────────────────────────
const authService = {
  /**
   * POST /auth/login
   * Retourne { token, user: { id, name, email, role } }
   */
  login: async ({ email, password }) => {
    const response = await api.post('/auth/login', { email, password });
    return extractAuth(response);
  },

  /**
   * POST /auth/register
   * Retourne { token, user }
   */
  register: async ({ name, email, phone, password }) => {
    const response = await api.post('/auth/register', { name, email, phone, password });
    return extractAuth(response);
  },

  /**
   * GET /auth/me — vérifie le token et retourne l'utilisateur courant
   */
  me: async () => {
    const response = await api.get('/auth/me');
    const rawUser = response.data?.data ?? response.data;
    return {
      id:    rawUser.id,
      name:  rawUser.name,
      email: rawUser.email,
      role:  normalizeRole(rawUser.role),
      active: rawUser.active,
    };
  },

  /** Injecte le token JWT dans tous les appels Axios suivants */
  setAuthHeader: (token) => {
    api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
  },

  /** Supprime le token des headers */
  removeAuthHeader: () => {
    delete api.defaults.headers.common['Authorization'];
  },
};

export { api };
export default authService;
